(509066, 50301, 10785, '<td valign="top">Why is the head of the nail showing here? Shouldn''t it be under the head of the hammer?<br/>I think that gives away the illusion you were trying to create of the hammer stirking the nail in your set-up shot.</td>', 'Why is the head of the nail showing here? Shouldn''t it be under the head of the hammer?I think that gives away the illusion you were trying to create of the hammer stirking the nail in your set-up shot.', '2003-12-10 10:13:00.000000', NULL, 1),
(509067, 49763, 2792, '<td valign="top">Awesome textures!  Very simple and elegant.  I bet this would have looked great in black and white too.</td>', 'Awesome textures!  Very simple and elegant.  I bet this would have looked great in black and white too.', '2003-12-10 10:13:10.000000', NULL, 1),
(509069, 50152, 543, '<td valign="top">Very low key.  Nice and soothing, but I''d like to see more white to balance the black and all those mid-tones.  Very nicely composed.</td>', 'Very low key.  Nice and soothing, but I''d like to see more white to balance the black and all those mid-tones.  Very nicely composed.', '2003-12-10 10:13:54.000000', NULL, 1),
(509071, 50049, 13136, '<td valign="top">Good mix of colors and focus on the main object. Right stem is blurred from a distant object?  That blur distracts from the whole.</td>', 'Good mix of colors and focus on the main object. Right stem is blurred from a distant object?  That blur distracts from the whole.', '2003-12-10 10:15:21.000000', NULL, 1),
(509072, 50105, 543, '<td valign="top">Beautiful light, nice crunchy tones and excellent sharpness here.</td>', 'Beautiful light, nice crunchy tones and excellent sharpness here.', '2003-12-10 10:15:25.000000', NULL, 1),
(509075, 50278, 13136, '<td valign="top">Great simplicity. Crop just a little farther out maybe?</td>', 'Great simplicity. Crop just a little farther out maybe?', '2003-12-10 10:16:29.000000', NULL, 1),
(509076, 50221, 10785, '<td valign="top">This needs more negative space!</td>', 'This needs more negative space!', '2003-12-10 10:16:31.000000', NULL, 1),
(509079, 50193, 10785, '<td valign="top">New York is complex and hard to understand for simple folk. Though a beautiful shot, in my opinion, it does not say simple. Though I do understand this is a simple, basic cityscape photo.</td>', 'New York is complex and hard to understand for simple folk. Though a beautiful shot, in my opinion, it does not say simple. Though I do understand this is a simple, basic cityscape photo.', '2003-12-10 10:18:55.000000', NULL, 1),
(509080, 49526, 543, '<td valign="top">Black and white would have more impact than the gray and gray you''ve got here.  Bump up the contrast, and maybe try for a less static composition and POV.  You were on a good track here, but could have pushed it a little to greater effect, IMO.</td>', 'Black and white would have more impact than the gray and gray you''ve got here.  Bump up the contrast, and maybe try for a less static composition and POV.  You were on a good track here, but could have pushed it a little to greater effect, IMO.', '2003-12-10 10:19:00.000000', NULL, 1),
(509081, 50313, 13136, '<td valign="top">Showing the flower in context with surroundings (as opposed to no surroundings) may get the simplicity theme across better. Nice shot.</td>', 'Showing the flower in context with surroundings (as opposed to no surroundings) may get the simplicity theme across better. Nice shot.', '2003-12-10 10:19:08.000000', NULL, 1),
(509082, 50324, 10785, '<td valign="top">This ranks up there with the Holy Tortilla from South America!</td>', 'This ranks up there with the Holy Tortilla from South America!', '2003-12-10 10:19:56.000000', NULL, 1),
(509083, 49813, 543, '<td valign="top">Simple, and anything but subtle.  Nicely done!</td>', 'Simple, and anything but subtle.  Nicely done!', '2003-12-10 10:20:02.000000', NULL, 1),
(509085, 50000, 13136, '<td valign="top">Crisp and clear and well composed. A bit too much light reflection.</td>', 'Crisp and clear and well composed. A bit too much light reflection.', '2003-12-10 10:20:59.000000', NULL, 1),
(509089, 50113, 13136, '<td valign="top">The dark rope does not work well with the dark background. That is actually a complex knot. Interesting red highlights.</td>', 'The dark rope does not work well with the dark background. That is actually a complex knot. Interesting red highlights.', '2003-12-10 10:22:44.000000', NULL, 1),
(509090, 49562, 7703, '<td valign="top">To dark. I just se some orange spots in the middle and lot of negative space</td>', 'To dark. I just se some orange spots in the middle and lot of negative space', '2003-12-10 10:23:15.000000', NULL, 1),
