(509093, 50202, 13136, '<td valign="top">The polarizing/saturation (or whatever effect it is) doesn''t work for me. This shot does not stand out. Sorry.</td>', 'The polarizing/saturation (or whatever effect it is) doesn''t work for me. This shot does not stand out. Sorry.', '2003-12-10 10:25:11.000000', NULL, 1),
