(509101, 50277, 13136, '<td valign="top">Wow. Nice negative space. Wouldn''t sunrise work better if it was from the bottom instead of the corner?</td>', 'Wow. Nice negative space. Wouldn''t sunrise work better if it was from the bottom instead of the corner?', '2003-12-10 10:27:26.000000', NULL, 1),
(509103, 49562, 13136, '<td valign="top">Sorry. I have my monitor turned up all the way and I can still hardly make out anything. Can''t tell what this is.</td>', 'Sorry. I have my monitor turned up all the way and I can still hardly make out anything. Can''t tell what this is.', '2003-12-10 10:28:14.000000', NULL, 1),
(509104, 50279, 10785, '<td valign="top">Very cute!</td>', 'Very cute!', '2003-12-10 10:28:14.000000', NULL, 1),
(509105, 50209, 10785, '<td valign="top">Simple and ordinary made to be extraordinary!</td>', 'Simple and ordinary made to be extraordinary!', '2003-12-10 10:28:56.000000', NULL, 1),
(509106, 50276, 14620, '<td valign="top">Doesn''t get much simpler than that!  Nice shot.</td>', 'Doesn''t get much simpler than that!  Nice shot.', '2003-12-10 10:29:03.000000', NULL, 1),
(509107, 49629, 13136, '<td valign="top">There just isn''t enough contrast to work with here. I can''t even tell if the object is in focus or not.</td>', 'There just isn''t enough contrast to work with here. I can''t even tell if the object is in focus or not.', '2003-12-10 10:29:21.000000', NULL, 1),
(509110, 50125, 10785, '<td valign="top">The glass does not look vertical. I can''t tell if it''s an optical illusion or if the frame is not horizontal. I will give the benefit of the doubt and says it''s me, not you!</td>', 'The glass does not look vertical. I can''t tell if it''s an optical illusion or if the frame is not horizontal. I will give the benefit of the doubt and says it''s me, not you!', '2003-12-10 10:31:04.000000', NULL, 1),
(509112, 49773, 14477, '<td valign="top">I would have liked this photo better with a more simple tablecloth.  I''m losing the bowl in the plaid.</td>', 'I would have liked this photo better with a more simple tablecloth.  I''m losing the bowl in the plaid.', '2003-12-10 10:34:21.000000', NULL, 1),
(509113, 50294, 8139, '<td valign="top">Overall interest : 1/3<br/>Technical : 2/3  (grainy, but it''s not disturbing here, the blur at right side shoud be more blurred, or not at all IMHO)<br/>Challenge fit : 2/2 <br/>Wow factor : 2/2 (for the abstract research, and aestetic)<br/></td>', 'Overall interest : 1/3Technical : 2/3  (grainy, but it''s not disturbing here, the blur at right side shoud be more blurred, or not at all IMHO)Challenge fit : 2/2 Wow factor : 2/2 (for the abstract research, and aestetic)', '2003-12-10 10:36:03.000000', NULL, 1),
(509115, 50226, 10785, '<td valign="top">Title needs to be more creative. The shot is simple enough and the viewer does not need to be forced to think a certain way here. (I say this because some shots with "simple" in the title are titled that way to make the shot fit the challenge, not needed here.)</td>', 'Title needs to be more creative. The shot is simple enough and the viewer does not need to be forced to think a certain way here. (I say this because some shots with "simple" in the title are titled that way to make the shot fit the challenge, not needed here.)', '2003-12-10 10:37:51.000000', NULL, 1),
(509119, 50285, 8139, '<td valign="top">Overall interest : 1/3<br/>Technical : 3/3  <br/>Challenge fit : 0/2 (this setup is too complicated, and i''ve no feeling of the "simplicity" concept)<br/>Wow factor : 0/2 (sorry)<br/></td>', 'Overall interest : 1/3Technical : 3/3  Challenge fit : 0/2 (this setup is too complicated, and i''ve no feeling of the "simplicity" concept)Wow factor : 0/2 (sorry)', '2003-12-10 10:38:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(509123, 50233, 7703, '<td valign="top">What take we for granted? It''s to much in this picture to see what you mean. Fence? Tree? -2</td>', 'What take we for granted? It''s to much in this picture to see what you mean. Fence? Tree? -2', '2003-12-10 10:40:16.000000', NULL, 1),
(509126, 50296, 10785, '<td valign="top">Even if this shot were for a technical manual or a highway design textbook it would still be boring! I do however want to recognize the effort you made to enter the contest! Here, here!</td>', 'Even if this shot were for a technical manual or a highway design textbook it would still be boring! I do however want to recognize the effort you made to enter the contest! Here, here!', '2003-12-10 10:41:32.000000', NULL, 1),
(509127, 50001, 14773, '<td valign="top">I love this shot, especially the color and you can feel some anticipation as if someone or something is about to eat it.</td>', 'I love this shot, especially the color and you can feel some anticipation as if someone or something is about to eat it.', '2003-12-10 10:41:57.000000', NULL, 1),
(509128, 50255, 10785, '<td valign="top">Cool!</td>', 'Cool!', '2003-12-10 10:42:17.000000', NULL, 1),
