(509172, 49788, 13136, '<td valign="top">Good use of negative space on top, maybe shift subject to one side or other. Picture says "Loneliness" more than "Simplicity" to me.</td>', 'Good use of negative space on top, maybe shift subject to one side or other. Picture says "Loneliness" more than "Simplicity" to me.', '2003-12-10 11:05:52.000000', NULL, 1),
(509174, 49495, 13136, '<td valign="top">Not sure taking the color out was right for this shot. Nice contract against the cloudy sky.</td>', 'Not sure taking the color out was right for this shot. Nice contract against the cloudy sky.', '2003-12-10 11:06:45.000000', NULL, 1),
(509175, 50317, 10785, '<td valign="top">Needs some foreground action or subject to be more interesting. As it stands, it''s not very interesting.<br/></td>', 'Needs some foreground action or subject to be more interesting. As it stands, it''s not very interesting.', '2003-12-10 11:07:14.000000', NULL, 1),
(509176, 49453, 13136, '<td valign="top">Pretty, but nothing special. Nice composition.</td>', 'Pretty, but nothing special. Nice composition.', '2003-12-10 11:07:37.000000', NULL, 1),
(509177, 49715, 13136, '<td valign="top">Nice macro. Hard to tell if it is grainy or if those are the real textures.</td>', 'Nice macro. Hard to tell if it is grainy or if those are the real textures.', '2003-12-10 11:09:08.000000', NULL, 1),
(509178, 49482, 9939, '<td valign="top">Technical: Most all images submitted fit the challenge, but this one not as strongly as the others for me. Exposure composition focus lighting okay but not imaginitive.<br/> <br/>Personal: For me this comes across as not much more than a snapshot, it isn''t compelling and it doesn''t illustrate simplicity for me.<br/> <br/>My vote: 3<br/></td>', 'Technical: Most all images submitted fit the challenge, but this one not as strongly as the others for me. Exposure composition focus lighting okay but not imaginitive. Personal: For me this comes across as not much more than a snapshot, it isn''t compelling and it doesn''t illustrate simplicity for me. My vote: 3', '2003-12-10 11:10:06.000000', NULL, 1),
(509179, 49698, 13136, '<td valign="top">I don''t like the uneven lighting on the subject. And it''s an ugly shell.</td>', 'I don''t like the uneven lighting on the subject. And it''s an ugly shell.', '2003-12-10 11:10:18.000000', NULL, 1),
(509180, 50159, 13136, '<td valign="top">Nice composition, lighting and color. good shot.</td>', 'Nice composition, lighting and color. good shot.', '2003-12-10 11:10:59.000000', NULL, 1),
(509181, 50302, 10785, '<td valign="top">Colored paint would have been cool! The brush is not in focus, which is probably caused by low lighting and an auto-focus camera, if I could take a guess as to why. Possibly no tripod used either. Excellent black background though!</td>', 'Colored paint would have been cool! The brush is not in focus, which is probably caused by low lighting and an auto-focus camera, if I could take a guess as to why. Possibly no tripod used either. Excellent black background though!', '2003-12-10 11:11:09.000000', NULL, 1),
(509182, 50136, 13136, '<td valign="top">I think a little more darkeness/contrast would help. Good focus and DOF.</td>', 'I think a little more darkeness/contrast would help. Good focus and DOF.', '2003-12-10 11:11:58.000000', NULL, 1),
(509184, 50271, 13136, '<td valign="top">Fits the challenge, but the subject doesn''t do anything for me.</td>', 'Fits the challenge, but the subject doesn''t do anything for me.', '2003-12-10 11:12:46.000000', NULL, 1),
(509185, 50191, 9939, '<td valign="top">Technical: Most all images submitted fit the challenge, but this one not as strongly as the others for me. Exposure composition focus lighting okay, but the reflections in the cat''s eyes is distracting and the crop is too tight for my taste, particularly with the look on the cat''s face.<br/> <br/>Personal: This looks like a stressed cat, this doesn''t say simplicity to me. It doesn''t look like much more than a snapshot. It appears to be properly exposed, but by the same token it looks too bright to me. Definitely worth the time to keep practicing!<br/> <br/>My vote: 3<br/></td>', 'Technical: Most all images submitted fit the challenge, but this one not as strongly as the others for me. Exposure composition focus lighting okay, but the reflections in the cat''s eyes is distracting and the crop is too tight for my taste, particularly with the look on the cat''s face. Personal: This looks like a stressed cat, this doesn''t say simplicity to me. It doesn''t look like much more than a snapshot. It appears to be properly exposed, but by the same token it looks too bright to me. Definitely worth the time to keep practicing! My vote: 3', '2003-12-10 11:12:56.000000', NULL, 1),
(509187, 50251, 13759, '<td valign="top">Really I can´t saw any simplicity in a blured Dog with the face in the snow. It´s refreshing of course... but what about simplicity?</td>', 'Really I can´t saw any simplicity in a blured Dog with the face in the snow. It´s refreshing of course... but what about simplicity?', '2003-12-10 11:13:22.000000', NULL, 1),
(509189, 50072, 10785, '<td valign="top">Think black boreder does not do this very cool photo justice.</td>', 'Think black boreder does not do this very cool photo justice.', '2003-12-10 11:13:46.000000', NULL, 1),
(509191, 50216, 13136, '<td valign="top">I might have had a bit more negative space, less harsh light and a colimentary color for the background. No points off for spelling though.</td>', 'I might have had a bit more negative space, less harsh light and a colimentary color for the background. No points off for spelling though.', '2003-12-10 11:14:59.000000', NULL, 1),
(509194, 49597, 9939, '<td valign="top">Technical: Most all images submitted fit the challenge. Exposure composition focus all okay, though the background is distracting. I feel the lighting is too harsh for a subject this cute, as evidenced by the strong shadow behind her!<br/> <br/>Personal: This comes across to me as not much more than a snapshot. Definitely worth the effort to keep practicing though!<br/> <br/>My vote: 3<br/></td>', 'Technical: Most all images submitted fit the challenge. Exposure composition focus all okay, though the background is distracting. I feel the lighting is too harsh for a subject this cute, as evidenced by the strong shadow behind her! Personal: This comes across to me as not much more than a snapshot. Definitely worth the effort to keep practicing though! My vote: 3', '2003-12-10 11:16:25.000000', NULL, 1),
(509195, 49899, 13136, '<td valign="top">Pretty shot. Are those birds or planes over the mountain? Foreground is a bit dark. I probably would have cropped most of it out..</td>', 'Pretty shot. Are those birds or planes over the mountain? Foreground is a bit dark. I probably would have cropped most of it out..', '2003-12-10 11:16:55.000000', NULL, 1),
(509196, 49681, 13759, '<td valign="top">I can see a complex subject with water drops (a extensive used theme). What about the simplicity?</td>', 'I can see a complex subject with water drops (a extensive used theme). What about the simplicity?', '2003-12-10 11:16:59.000000', NULL, 1),
(509197, 50301, 13759, '<td valign="top">Finally something simple!</td>', 'Finally something simple!', '2003-12-10 11:17:34.000000', NULL, 1),
