(509731, 50171, 259, '<td valign="top">i love this shot</td>', 'i love this shot', '2003-12-10 15:23:58.000000', NULL, 1),
(509732, 50308, 9939, '<td valign="top">Technical: Most all images submitted fit the challenge. This does well! Exposure composition focus lighting all good, though I''d like to see the subject better protected from reflections and glare.<br/> <br/>Personal: Excellent fit to the challenge. Simply a great idea!<br/> <br/>My vote: 7<br/></td>', 'Technical: Most all images submitted fit the challenge. This does well! Exposure composition focus lighting all good, though I''d like to see the subject better protected from reflections and glare. Personal: Excellent fit to the challenge. Simply a great idea! My vote: 7', '2003-12-10 15:25:29.000000', NULL, 1),
(509734, 49792, 10858, '<td valign="top">The lean in the foreground is a bit distracting for me, but this is a very nice composition. I wonder why you have desaturated all colours except blues. I think a full desaturation and sepia tones would have made it, too. :-) Just an opinion.</td>', 'The lean in the foreground is a bit distracting for me, but this is a very nice composition. I wonder why you have desaturated all colours except blues. I think a full desaturation and sepia tones would have made it, too. :-) Just an opinion.', '2003-12-10 15:30:38.000000', NULL, 1),
