(510831, 49548, 10985, '<td valign="top">What a great idea and effect! Very effective. I would suggest, for the non-contest version that the largest drop be cloned out. (9)</td>', 'What a great idea and effect! Very effective. I would suggest, for the non-contest version that the largest drop be cloned out. (9)', '2003-12-11 14:29:38.000000', NULL, 1),
(510832, 50092, 10985, '<td valign="top">Excellent idea and format, but to me, the pill is much too soft.</td>', 'Excellent idea and format, but to me, the pill is much too soft.', '2003-12-11 14:30:17.000000', NULL, 1),
(510833, 49601, 11155, '<td valign="top">Great colors, good composition, and nice even lighting.  This is wonderfully... simplistic.  Good luck.</td>', 'Great colors, good composition, and nice even lighting.  This is wonderfully... simplistic.  Good luck.', '2003-12-11 14:30:40.000000', NULL, 1),
