(510835, 50209, 10985, '<td valign="top">Moody! I like it.</td>', 'Moody! I like it.', '2003-12-11 14:31:25.000000', NULL, 1),
(510836, 50036, 11155, '<td valign="top">I like the colors in this - they work well together.  Sharp and soft at the same time.  Nice.</td>', 'I like the colors in this - they work well together.  Sharp and soft at the same time.  Nice.', '2003-12-11 14:31:26.000000', NULL, 1),
(510838, 50076, 10985, '<td valign="top">A little closer would give it more impact, IMHO. Good idea and colors.</td>', 'A little closer would give it more impact, IMHO. Good idea and colors.', '2003-12-11 14:31:56.000000', NULL, 1),
(510839, 50172, 11155, '<td valign="top">Evil, huh?  Somebody''s bitter.  Composition is good, as is the lighting.</td>', 'Evil, huh?  Somebody''s bitter.  Composition is good, as is the lighting.', '2003-12-11 14:32:18.000000', NULL, 1),
(510840, 50038, 10985, '<td valign="top">Funny and very sharp.</td>', 'Funny and very sharp.', '2003-12-11 14:32:21.000000', NULL, 1),
(510841, 50099, 10985, '<td valign="top">Very serene.</td>', 'Very serene.', '2003-12-11 14:32:36.000000', NULL, 1),
(510842, 50244, 11155, '<td valign="top">Wonderful background.  Great color contrast too.</td>', 'Wonderful background.  Great color contrast too.', '2003-12-11 14:32:57.000000', NULL, 1),
