INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(510846, 50244, 10985, '<td valign="top">Beautiful bg and very simple composition, yet very rich in color.</td>', 'Beautiful bg and very simple composition, yet very rich in color.', '2003-12-11 14:35:24.000000', NULL, 1),
(510847, 49600, 10985, '<td valign="top">Excellent composition and simplicity. Too bad it''s so blurry...</td>', 'Excellent composition and simplicity. Too bad it''s so blurry...', '2003-12-11 14:36:52.000000', NULL, 1),
(510850, 49763, 10985, '<td valign="top">Beautiful evening light!</td>', 'Beautiful evening light!', '2003-12-11 14:37:57.000000', NULL, 1),
(510852, 49779, 10985, '<td valign="top">Funny! A bit dark, but it brought a smile to my face.</td>', 'Funny! A bit dark, but it brought a smile to my face.', '2003-12-11 14:41:49.000000', NULL, 1),
(510853, 50304, 10985, '<td valign="top">Very appealing. The softness actually adds to the strength of this photo. Beautiful.</td>', 'Very appealing. The softness actually adds to the strength of this photo. Beautiful.', '2003-12-11 14:42:32.000000', NULL, 1),
(510854, 49562, 10858, '<td valign="top">Maybe a bit too simple for me, and too much negative space here (I mean, your main subject could be a bit bigger). After voting is over, please, tell me what this is exactly. :-)</td>', 'Maybe a bit too simple for me, and too much negative space here (I mean, your main subject could be a bit bigger). After voting is over, please, tell me what this is exactly. :-)', '2003-12-11 14:42:56.000000', NULL, 1),
(510856, 50113, 10985, '<td valign="top">I love the touch of red at the bottom. Very well thought. I hope you''re ok... ;o}</td>', 'I love the touch of red at the bottom. Very well thought. I hope you''re ok... ;o}', '2003-12-11 14:45:01.000000', NULL, 1),
(510857, 49790, 10023, '<td valign="top">It''s wonderful... the bright light spot just steals too much attention. :/ Without it, I would''ve given it a 10.</td>', 'It''s wonderful... the bright light spot just steals too much attention. :/ Without it, I would''ve given it a 10.', '2003-12-11 14:45:32.000000', NULL, 1),
(510858, 50146, 13136, '<td valign="top">I''m sorry, but I have no idea what this is. I''ve looked at it several times and for long streatches, but can''t see anything redeeming in this shot.</td>', 'I''m sorry, but I have no idea what this is. I''ve looked at it several times and for long streatches, but can''t see anything redeeming in this shot.', '2003-12-11 14:45:50.000000', NULL, 1),
(510859, 50110, 10858, '<td valign="top">This is wonderful! Colours are amazing - few and effective, and lighting is spot on. I love the textile being so soft. Cropping is not even on the two sides, but it works well for me, because the textile is forming an also-not-simmetric upside-down "V" on the top of the photo.Maybe the Christmas ornaments are a bit decorative for my taste of simplicity, but as it''s a simple pattern, it may be okay. :-)</td>', 'This is wonderful! Colours are amazing - few and effective, and lighting is spot on. I love the textile being so soft. Cropping is not even on the two sides, but it works well for me, because the textile is forming an also-not-simmetric upside-down "V" on the top of the photo.Maybe the Christmas ornaments are a bit decorative for my taste of simplicity, but as it''s a simple pattern, it may be okay. :-)', '2003-12-11 14:46:51.000000', NULL, 1),
(510860, 50327, 13136, '<td valign="top">Lovely shot. Would have done well in the "Soft Focus" challenge as well. I like how the direction and level of the light make the trees silhouettes.</td>', 'Lovely shot. Would have done well in the "Soft Focus" challenge as well. I like how the direction and level of the light make the trees silhouettes.', '2003-12-11 14:47:02.000000', NULL, 1),
(510861, 49983, 10985, '<td valign="top">Oh my God! She looks dead in the water! Well done but spooky.</td>', 'Oh my God! She looks dead in the water! Well done but spooky.', '2003-12-11 14:47:08.000000', NULL, 1),
(510862, 49855, 10985, '<td valign="top">Funny!</td>', 'Funny!', '2003-12-11 14:47:37.000000', NULL, 1),
(510863, 50133, 10985, '<td valign="top">Computer? A greater DoF would make it even stronger.</td>', 'Computer? A greater DoF would make it even stronger.', '2003-12-11 14:48:27.000000', NULL, 1),
(510864, 50227, 10858, '<td valign="top">Focus could be improved, the texts seem to be blurry and the bottom of the equipment as well. You should have focused to the Nintendo text if you were to follow your title.</td>', 'Focus could be improved, the texts seem to be blurry and the bottom of the equipment as well. You should have focused to the Nintendo text if you were to follow your title.', '2003-12-11 14:49:17.000000', NULL, 1),
(510865, 50125, 10985, '<td valign="top">Very cool and intriguing. I''ve got to try that myself! I would have cropped the right side much closer to the glass, to decenter it.</td>', 'Very cool and intriguing. I''ve got to try that myself! I would have cropped the right side much closer to the glass, to decenter it.', '2003-12-11 14:49:52.000000', NULL, 1),
(510867, 50083, 13136, '<td valign="top">Very "comfy" shot. Makes me feel like curling up in front of a fire with a mug of hot chocolate. The picture seems to be just a bit faded, but It may just be the morning snowy haze, I can''t tell. Would be better if it was a bit crisper. Still, a good shot.</td>', 'Very "comfy" shot. Makes me feel like curling up in front of a fire with a mug of hot chocolate. The picture seems to be just a bit faded, but It may just be the morning snowy haze, I can''t tell. Would be better if it was a bit crisper. Still, a good shot.', '2003-12-11 14:50:33.000000', NULL, 1),
(510869, 50224, 10985, '<td valign="top">Beautifully done. A blue bg would have given this the 3 primary colors, but the impact is still very good here.</td>', 'Beautifully done. A blue bg would have given this the 3 primary colors, but the impact is still very good here.', '2003-12-11 14:51:36.000000', NULL, 1),
(510870, 50111, 13136, '<td valign="top">A little small and there is a line of some sort running across the middle of the picture. Otherwise, a nice shot.</td>', 'A little small and there is a line of some sort running across the middle of the picture. Otherwise, a nice shot.', '2003-12-11 14:51:36.000000', NULL, 1),
(510871, 50011, 10985, '<td valign="top">Fun! Great colors, too.</td>', 'Fun! Great colors, too.', '2003-12-11 14:51:58.000000', NULL, 1),
(510873, 49751, 11155, '<td valign="top">Great colors, very serene.  Well composed.</td>', 'Great colors, very serene.  Well composed.', '2003-12-11 14:52:37.000000', NULL, 1),
(510874, 49714, 10985, '<td valign="top">I like this crop very much. Good toning, too. A little soft, though.</td>', 'I like this crop very much. Good toning, too. A little soft, though.', '2003-12-11 14:53:07.000000', NULL, 1),
(510877, 50000, 10985, '<td valign="top">Very sharp and great shadows and composition.</td>', 'Very sharp and great shadows and composition.', '2003-12-11 14:53:45.000000', NULL, 1),
(510878, 50233, 10858, '<td valign="top">The fence is blurry, especially on the right. If you want everything sharp, you should use apertures like f/16 or f/22 - I have just learnt it -, it helps you get everything in focus.</td>', 'The fence is blurry, especially on the right. If you want everything sharp, you should use apertures like f/16 or f/22 - I have just learnt it -, it helps you get everything in focus.', '2003-12-11 14:54:15.000000', NULL, 1),
(510879, 50330, 10985, '<td valign="top">A little soft but very well presented.</td>', 'A little soft but very well presented.', '2003-12-11 14:54:49.000000', NULL, 1),
(510880, 50295, 10985, '<td valign="top">Now that''s a great idea! Very well done.</td>', 'Now that''s a great idea! Very well done.', '2003-12-11 14:55:36.000000', NULL, 1),
(510881, 50277, 10985, '<td valign="top">Good idea, excellent colors (complementary, too!) and composition.</td>', 'Good idea, excellent colors (complementary, too!) and composition.', '2003-12-11 14:57:36.000000', NULL, 1),
(510884, 50143, 10985, '<td valign="top">Cool!</td>', 'Cool!', '2003-12-11 14:59:24.000000', NULL, 1),
(510885, 50322, 10858, '<td valign="top">This is one of the best moon shots I have ever seen! :-) Nice for simplicity, would fit shapes as well. I guess it''s a lo-key photo, isn''t it? :-) I like it very much!</td>', 'This is one of the best moon shots I have ever seen! :-) Nice for simplicity, would fit shapes as well. I guess it''s a lo-key photo, isn''t it? :-) I like it very much!', '2003-12-11 14:59:44.000000', NULL, 1),
(510886, 50324, 10858, '<td valign="top">This could be sharper, it is too blurry for me, and I can''t deceide where to look exactly. Simple and abstact, but quality could be improved in my opinion.</td>', 'This could be sharper, it is too blurry for me, and I can''t deceide where to look exactly. Simple and abstact, but quality could be improved in my opinion.', '2003-12-11 15:02:34.000000', NULL, 1),
(510888, 50249, 10858, '<td valign="top">Simple shapes, but a bit many colours for my personal taste. You could have used a bit more depth of fields, the objects in the back could be sharper as they are part of your main subject(s).</td>', 'Simple shapes, but a bit many colours for my personal taste. You could have used a bit more depth of fields, the objects in the back could be sharper as they are part of your main subject(s).', '2003-12-11 15:05:27.000000', NULL, 1),
(510891, 49622, 10985, '<td valign="top">Great colors and sky. I like the addition of the moon. Nice composition.</td>', 'Great colors and sky. I like the addition of the moon. Nice composition.', '2003-12-11 15:07:47.000000', NULL, 1),
(510892, 50053, 10985, '<td valign="top">I''m not sure how I like the composition, but I love your subject and the perfect sharpness.</td>', 'I''m not sure how I like the composition, but I love your subject and the perfect sharpness.', '2003-12-11 15:08:30.000000', NULL, 1),
(510894, 50304, 10858, '<td valign="top">Simple, indeed, I like the snowflake-shape a much. :-) Could be in the left bottom corner so the skater and it would give the diagonal to the photo. I guess you wanted to go for rules of thirds, but sometimes it''s good to break the rules. :-) I would see the skater more sharper, too, maybe a quicker shutter would have helped you. I like that his movement has a direction to the bottom left corner, this is why I would have composed the snowflake there. Just an opinion.</td>', 'Simple, indeed, I like the snowflake-shape a much. :-) Could be in the left bottom corner so the skater and it would give the diagonal to the photo. I guess you wanted to go for rules of thirds, but sometimes it''s good to break the rules. :-) I would see the skater more sharper, too, maybe a quicker shutter would have helped you. I like that his movement has a direction to the bottom left corner, this is why I would have composed the snowflake there. Just an opinion.', '2003-12-11 15:09:04.000000', NULL, 1),
(510896, 49443, 10858, '<td valign="top">The photo is a bit blurry, and I think lighting is not enough as the whole photo gets a greyish tone. I wouldn''t have centered Her, I would have composed her more to the right, She could have enough negative space in front of Her for Her thoughts and prayers. A bit fining on the lighting could have made you avoid gleams on the statue. The idea is nice, and pastell tones are good for the photo''s simplicity, too.</td>', 'The photo is a bit blurry, and I think lighting is not enough as the whole photo gets a greyish tone. I wouldn''t have centered Her, I would have composed her more to the right, She could have enough negative space in front of Her for Her thoughts and prayers. A bit fining on the lighting could have made you avoid gleams on the statue. The idea is nice, and pastell tones are good for the photo''s simplicity, too.', '2003-12-11 15:13:32.000000', NULL, 1),
(510898, 50076, 10858, '<td valign="top">I am not sure about the waterdrops, for my personal taste a more homogenic background would be more fine. I also would have followed the rule of thirds when placing your feather. Just a little bit to te left. It could be bigger as well, too. White and orange are nice together.</td>', 'I am not sure about the waterdrops, for my personal taste a more homogenic background would be more fine. I also would have followed the rule of thirds when placing your feather. Just a little bit to te left. It could be bigger as well, too. White and orange are nice together.', '2003-12-11 15:17:01.000000', NULL, 1),
(510899, 50277, 11155, '<td valign="top">Wonderful colors and composition.  Looks like some compression in the background, but no deduction for that.</td>', 'Wonderful colors and composition.  Looks like some compression in the background, but no deduction for that.', '2003-12-11 15:17:54.000000', NULL, 1),
(510901, 49681, 11155, '<td valign="top">Wonderful image!  Very creative - colors are great.  Must be an EOS10D, haha.<br/>I think I may have liked this with an all blue background, but this is really great!</td>', 'Wonderful image!  Very creative - colors are great.  Must be an EOS10D, haha.I think I may have liked this with an all blue background, but this is really great!', '2003-12-11 15:21:54.000000', NULL, 1),
(510902, 50313, 10858, '<td valign="top">Wonderful composition, beautiful simple colours here. :-) Although I would like to see the rest of the flower on the left, I love this shot a much! :-)</td>', 'Wonderful composition, beautiful simple colours here. :-) Although I would like to see the rest of the flower on the left, I love this shot a much! :-)', '2003-12-11 15:22:22.000000', NULL, 1),
(510903, 50262, 11155, '<td valign="top">What an original image.  I reallyl ike this.  Fits the challenge well and is fun to look at.  Nice work.</td>', 'What an original image.  I reallyl ike this.  Fits the challenge well and is fun to look at.  Nice work.', '2003-12-11 15:23:01.000000', NULL, 1),
(510905, 50275, 10858, '<td valign="top">This is simple! :-) I like the transparent pins have the same colour like the background. How did you do that? Was it something in the lighting or have you adjusted white-balance? Beautiful, sharp and simple macro photo, congrats!</td>', 'This is simple! :-) I like the transparent pins have the same colour like the background. How did you do that? Was it something in the lighting or have you adjusted white-balance? Beautiful, sharp and simple macro photo, congrats!', '2003-12-11 15:25:02.000000', NULL, 1),
(510908, 49859, 10858, '<td valign="top">Provocative one, breaking the rule of thirds, but I like it this way. :-) Colours are very fine together and I think your border helps your photo constructively. The handle breaks the symmetric composition and I love this effect, too!</td>', 'Provocative one, breaking the rule of thirds, but I like it this way. :-) Colours are very fine together and I think your border helps your photo constructively. The handle breaks the symmetric composition and I love this effect, too!', '2003-12-11 15:27:59.000000', NULL, 1),
(510911, 50232, 10858, '<td valign="top">The flat diagonal composition and colours are fine here, and the idea is unique. :-) I like this photo very much! :-) Maybe I would like the text to be sharp enough to read.</td>', 'The flat diagonal composition and colours are fine here, and the idea is unique. :-) I like this photo very much! :-) Maybe I would like the text to be sharp enough to read.', '2003-12-11 15:32:11.000000', NULL, 1),
(510912, 50324, 3569, '<td valign="top">I see a laughing duck, but nothing else</td>', 'I see a laughing duck, but nothing else', '2003-12-11 15:32:54.000000', NULL, 1),
(510913, 50099, 3569, '<td valign="top">IMO I would have like to see more ground than trees.  I like it though</td>', 'IMO I would have like to see more ground than trees.  I like it though', '2003-12-11 15:35:06.000000', NULL, 1),
(510914, 50194, 3569, '<td valign="top">Nice soft focus.</td>', 'Nice soft focus.', '2003-12-11 15:37:45.000000', NULL, 1),
(510915, 50145, 3569, '<td valign="top">Nice contrasts and dof</td>', 'Nice contrasts and dof', '2003-12-11 15:38:47.000000', NULL, 1),
(510919, 49918, 3569, '<td valign="top">Nice portrate.  Colors and dof right on.</td>', 'Nice portrate.  Colors and dof right on.', '2003-12-11 15:40:52.000000', NULL, 1),
(510920, 50089, 3569, '<td valign="top">focus appears to be off on the ant (subject?)</td>', 'focus appears to be off on the ant (subject?)', '2003-12-11 15:43:00.000000', NULL, 1),
(510921, 49911, 3569, '<td valign="top">Nice portrait</td>', 'Nice portrait', '2003-12-11 15:44:00.000000', NULL, 1),
(510923, 50006, 3569, '<td valign="top">A bit more contrast would have made it nicer.</td>', 'A bit more contrast would have made it nicer.', '2003-12-11 15:46:02.000000', NULL, 1),
(510927, 49991, 3569, '<td valign="top">Nice mallard</td>', 'Nice mallard', '2003-12-11 15:46:39.000000', NULL, 1),
(510930, 49916, 3569, '<td valign="top">Oh my, its falling off the page.  In other words, I do not like the angle.</td>', 'Oh my, its falling off the page.  In other words, I do not like the angle.', '2003-12-11 15:48:51.000000', NULL, 1),
(510931, 50077, 3569, '<td valign="top">Great cropping and subject.</td>', 'Great cropping and subject.', '2003-12-11 15:50:49.000000', NULL, 1),
(510932, 49736, 10858, '<td valign="top">I love the bluey negative photo effect here very much! Composition is great, lighting is perfect. This reminds me to my Zenit TTL camera. After yhe voting, please tell me, how did you make this effect! :-)</td>', 'I love the bluey negative photo effect here very much! Composition is great, lighting is perfect. This reminds me to my Zenit TTL camera. After yhe voting, please tell me, how did you make this effect! :-)', '2003-12-11 15:51:28.000000', NULL, 1),
(510935, 50024, 3569, '<td valign="top">flash a bit harsh</td>', 'flash a bit harsh', '2003-12-11 15:53:32.000000', NULL, 1),
(510936, 49806, 3569, '<td valign="top">A bit more dof and ya got a 10</td>', 'A bit more dof and ya got a 10', '2003-12-11 15:54:16.000000', NULL, 1),
(510950, 50310, 13354, '<td valign="top">I would have prefered the color version.</td>', 'I would have prefered the color version.', '2003-12-11 16:18:36.000000', NULL, 1),
(510953, 49812, 13354, '<td valign="top">I think it''s missing a focal point.</td>', 'I think it''s missing a focal point.', '2003-12-11 16:22:46.000000', NULL, 1),
(510959, 50194, 13354, '<td valign="top">I thought women were complex?!?</td>', 'I thought women were complex?!?', '2003-12-11 16:31:42.000000', NULL, 1),
(510963, 50025, 12268, '<td valign="top">Nice bw shot. I think there is a bit too much going on though. Perhaps if the fence were cropped out or if this was shot at an angle excluding it. although the fence does add something to the shot, just might be a bit much for this particular challenge. Good stuff regardless!</td>', 'Nice bw shot. I think there is a bit too much going on though. Perhaps if the fence were cropped out or if this was shot at an angle excluding it. although the fence does add something to the shot, just might be a bit much for this particular challenge. Good stuff regardless!', '2003-12-11 16:36:44.000000', NULL, 1),
