(511360, 49526, 10084, '<td valign="top"><b>+</b>Composition is interesting. Great subject matter. I like the horizontal line going across the shot. Contrast is decent.<br/><b>-</b>Lighting on the cube is great. I wished that the ball and the cone were as well lit. The shadow off the cone on the wall is a bit distracting.<br/><b>Score</b> 9</td>', '+Composition is interesting. Great subject matter. I like the horizontal line going across the shot. Contrast is decent.-Lighting on the cube is great. I wished that the ball and the cone were as well lit. The shadow off the cone on the wall is a bit distracting.Score 9', '2003-12-12 08:02:45.000000', NULL, 1),
(511361, 50224, 10084, '<td valign="top"><b>+</b>Interesting subject matter. Good composition. Very vibrant colors.Amazing lighting. Incredible that the highlights are so subtle.<br/><b>-</b>None<br/><b>Score</b>10</td>', '+Interesting subject matter. Good composition. Very vibrant colors.Amazing lighting. Incredible that the highlights are so subtle.-NoneScore10', '2003-12-12 08:05:51.000000', NULL, 1),
(511364, 50110, 11155, '<td valign="top">I like this - the red overtone (subject and background) are great.  Lighting is nice too.</td>', 'I like this - the red overtone (subject and background) are great.  Lighting is nice too.', '2003-12-12 08:08:36.000000', NULL, 1),
