(511368, 50276, 10084, '<td valign="top"><b>+</b>Great composition. Very good focus. Simple yet impressive shot.<br/><b>-</b>Some of the highlights are a bit much, especially at the curves.<br/><b>Score</b>10</td>', '+Great composition. Very good focus. Simple yet impressive shot.-Some of the highlights are a bit much, especially at the curves.Score10', '2003-12-12 08:11:20.000000', NULL, 1),
(511370, 50154, 11155, '<td valign="top">This is a really cool shot, but I''m not sure that it reflects simplicity.  The multiple lines and lighting seem more complex than simple.  Again, a wonderful shot, just maybe for a different category.</td>', 'This is a really cool shot, but I''m not sure that it reflects simplicity.  The multiple lines and lighting seem more complex than simple.  Again, a wonderful shot, just maybe for a different category.', '2003-12-12 08:23:47.000000', NULL, 1),
(511371, 50276, 5728, '<td valign="top">You are right it was Johan Waaler who invented the paper clip. And I was always told it was invented in New Zealand :( Anyway lovely pic, nice effect with the shadow (9)<br/></td>', 'You are right it was Johan Waaler who invented the paper clip. And I was always told it was invented in New Zealand :( Anyway lovely pic, nice effect with the shadow (9)', '2003-12-12 08:31:37.000000', NULL, 1),
(511376, 50152, 11155, '<td valign="top">Great tonality and softness to this.  Shadows work extremely well.  Excellent.</td>', 'Great tonality and softness to this.  Shadows work extremely well.  Excellent.', '2003-12-12 08:42:12.000000', NULL, 1),
(511377, 50287, 11155, '<td valign="top">Great colors and lighting.  I like the gold tone to this image.  ONly change I''d make is to show more space under the ornament to give more of a hanging feel.  The focus seems to be just a little off (branch at top of ornament is in focus, but top of ornament isn''t)  Not enough to deduct from the score, though.</td>', 'Great colors and lighting.  I like the gold tone to this image.  ONly change I''d make is to show more space under the ornament to give more of a hanging feel.  The focus seems to be just a little off (branch at top of ornament is in focus, but top of ornament isn''t)  Not enough to deduct from the score, though.', '2003-12-12 08:44:38.000000', NULL, 1),
(511378, 50312, 11155, '<td valign="top">Love this.  Great framing/composition.  Silver and whites are great.  Sharp, too.</td>', 'Love this.  Great framing/composition.  Silver and whites are great.  Sharp, too.', '2003-12-12 08:45:39.000000', NULL, 1),
(511379, 50196, 11155, '<td valign="top">NIce.  The ol'' one button mouse.  Nicely framed.  Like the background.</td>', 'NIce.  The ol'' one button mouse.  Nicely framed.  Like the background.', '2003-12-12 08:46:21.000000', NULL, 1),
