(512092, 49918, 2302, '<td valign="top">beautiful portrait - doesn''t say simplicity (to me)  though</td>', 'beautiful portrait - doesn''t say simplicity (to me)  though', '2003-12-13 11:48:33.000000', NULL, 1),
