(512169, 50034, 5792, '<td valign="top">Reminds one of "Pianissimo", that very fine image by jmsetzler that placed 3rd in the Soft Focus challenge. This is a very fine image I''d be proud to have taken myself.</td>', 'Reminds one of "Pianissimo", that very fine image by jmsetzler that placed 3rd in the Soft Focus challenge. This is a very fine image I''d be proud to have taken myself.', '2003-12-13 15:18:52.000000', NULL, 1),
(512173, 49859, 5792, '<td valign="top">You framed this image impeccably. Nice work.</td>', 'You framed this image impeccably. Nice work.', '2003-12-13 15:22:06.000000', NULL, 1),
(512175, 49736, 5792, '<td valign="top">Normally negative images and pictures of cameras have little appeal in challenges. But the high technical quality of this one overcomes that. Very good job.</td>', 'Normally negative images and pictures of cameras have little appeal in challenges. But the high technical quality of this one overcomes that. Very good job.', '2003-12-13 15:25:10.000000', NULL, 1),
(512176, 49505, 5792, '<td valign="top">The way you have highlighted the reflected sky color without including the sky is a refreshing and unique variation of a sunset.</td>', 'The way you have highlighted the reflected sky color without including the sky is a refreshing and unique variation of a sunset.', '2003-12-13 15:26:47.000000', NULL, 1),
(512178, 50113, 5792, '<td valign="top">The red highlights on the rope gives this image a powerful and meaningful appearance. You are to be commended.<br/> <br/>The image is incredible as is but centering the rope on the left 1/3rd of the frame to add extended black negative space to the right might add even more power to it.</td>', 'The red highlights on the rope gives this image a powerful and meaningful appearance. You are to be commended. The image is incredible as is but centering the rope on the left 1/3rd of the frame to add extended black negative space to the right might add even more power to it.', '2003-12-13 15:33:30.000000', NULL, 1),
(512179, 50279, 5792, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2003-12-13 15:33:58.000000', NULL, 1),
(512180, 50327, 5792, '<td valign="top">Very nicely done. It is one of my favorites. This might have been even more appealing if you centered the morning sun on the left or right 1/3rd horizontal quadrant.</td>', 'Very nicely done. It is one of my favorites. This might have been even more appealing if you centered the morning sun on the left or right 1/3rd horizontal quadrant.', '2003-12-13 15:36:51.000000', NULL, 1),
(512181, 50102, 5792, '<td valign="top">You see the ordinary in a unique, perceptive wa. It is an essential skill for every photographer. Very well done image.</td>', 'You see the ordinary in a unique, perceptive wa. It is an essential skill for every photographer. Very well done image.', '2003-12-13 15:40:44.000000', NULL, 1),
(512182, 50152, 5792, '<td valign="top">Very interesting image. You masterfully captured just the dark grey scale.  It gives this image a unique appeal.</td>', 'Very interesting image. You masterfully captured just the dark grey scale.  It gives this image a unique appeal.', '2003-12-13 15:43:19.000000', NULL, 1),
(512184, 49918, 5792, '<td valign="top">You have captured an great philosophic expression on someone so very young. Good job.</td>', 'You have captured an great philosophic expression on someone so very young. Good job.', '2003-12-13 15:45:14.000000', NULL, 1),
(512186, 49751, 5792, '<td valign="top">Nicely done. You resisted the temptation to overprocess this image. Many of us would would not.</td>', 'Nicely done. You resisted the temptation to overprocess this image. Many of us would would not.', '2003-12-13 15:47:44.000000', NULL, 1),
(512187, 50054, 5792, '<td valign="top">Nice perspective. Nice idea.</td>', 'Nice perspective. Nice idea.', '2003-12-13 15:48:18.000000', NULL, 1),
(512189, 50206, 5792, '<td valign="top">Well framed.</td>', 'Well framed.', '2003-12-13 15:51:35.000000', NULL, 1),
(512190, 49893, 5792, '<td valign="top">Very good macro. There is "haloing" visible on the leaves that is slightly distracting, but overall this is an super entry.</td>', 'Very good macro. There is "haloing" visible on the leaves that is slightly distracting, but overall this is an super entry.', '2003-12-13 15:53:47.000000', NULL, 1),
(512191, 50053, 5792, '<td valign="top">Beautifully conceived image for this challenge.</td>', 'Beautifully conceived image for this challenge.', '2003-12-13 15:54:24.000000', NULL, 1),
(512193, 50074, 5792, '<td valign="top">Great use of primary colors and nice compliance to the ROT.</td>', 'Great use of primary colors and nice compliance to the ROT.', '2003-12-13 15:55:47.000000', NULL, 1),
(512195, 49853, 5792, '<td valign="top">Nice job with white on white.</td>', 'Nice job with white on white.', '2003-12-13 15:56:15.000000', NULL, 1),
(512196, 50277, 5792, '<td valign="top">Solid blue and yellow work well with this image. Exceptional technical quality and composed very well.</td>', 'Solid blue and yellow work well with this image. Exceptional technical quality and composed very well.', '2003-12-13 15:58:32.000000', NULL, 1),
(512198, 49622, 5792, '<td valign="top">The soft perspective reminds me of one of my recent images where I used Neat Image to get the result. It is a good effect.</td>', 'The soft perspective reminds me of one of my recent images where I used Neat Image to get the result. It is a good effect.', '2003-12-13 16:04:52.000000', NULL, 1),
(512199, 50289, 5792, '<td valign="top">Very unique B&amp;W. It only needs to be rotated about .5 degrees or so counter clockwise to be perfect.</td>', 'Very unique B&W. It only needs to be rotated about .5 degrees or so counter clockwise to be perfect.', '2003-12-13 16:07:35.000000', NULL, 1),
(512200, 49619, 5792, '<td valign="top">Good composition and framing.</td>', 'Good composition and framing.', '2003-12-13 16:08:36.000000', NULL, 1),
(512201, 49763, 5792, '<td valign="top">Elegant in its simplicity. If anything it should be a little softer focus.</td>', 'Elegant in its simplicity. If anything it should be a little softer focus.', '2003-12-13 16:09:37.000000', NULL, 1),
(512204, 50223, 5792, '<td valign="top">Excellant attention to framing detail on this image.</td>', 'Excellant attention to framing detail on this image.', '2003-12-13 16:11:42.000000', NULL, 1),
(512205, 50159, 14401, '<td valign="top">I like the color and clean lines here - also that you kept all nicely focused - not too much DOF - sometimes a little of that goes a long way.</td>', 'I like the color and clean lines here - also that you kept all nicely focused - not too much DOF - sometimes a little of that goes a long way.', '2003-12-13 16:12:28.000000', NULL, 1),
(512206, 49669, 14601, '<td valign="top">Nice composition, great idea, nicely lit; no real hot spots, and a nice soft shadow on the right. A bit too much white for me, personally. Perhaps just a little tighter crop on the left would help?</td>', 'Nice composition, great idea, nicely lit; no real hot spots, and a nice soft shadow on the right. A bit too much white for me, personally. Perhaps just a little tighter crop on the left would help?', '2003-12-13 16:12:32.000000', NULL, 1),
(512208, 49773, 14401, '<td valign="top">Nice concept, but the colors don''t work too well IMHO - doesn''t really look appetizing.</td>', 'Nice concept, but the colors don''t work too well IMHO - doesn''t really look appetizing.', '2003-12-13 16:13:34.000000', NULL, 1),
(512211, 50264, 5792, '<td valign="top">Very nice pastoral scene. Well composed.</td>', 'Very nice pastoral scene. Well composed.', '2003-12-13 16:14:35.000000', NULL, 1),
(512212, 50125, 5792, '<td valign="top">Good job. The image needs to be rotated about 1 degree clockwise, or that might be purposely intended to indicate an unbalanced center of gravity.</td>', 'Good job. The image needs to be rotated about 1 degree clockwise, or that might be purposely intended to indicate an unbalanced center of gravity.', '2003-12-13 16:17:46.000000', NULL, 1),
(512214, 49873, 5792, '<td valign="top">Good idea for this time of year.</td>', 'Good idea for this time of year.', '2003-12-13 16:18:42.000000', NULL, 1),
(512215, 49733, 5792, '<td valign="top">Ah, Grasshopper, always seek peace and tranquility but don''t forget to honor your father.</td>', 'Ah, Grasshopper, always seek peace and tranquility but don''t forget to honor your father.', '2003-12-13 16:20:30.000000', NULL, 1),
(512217, 50009, 5792, '<td valign="top">I thought I was the only one that did that.</td>', 'I thought I was the only one that did that.', '2003-12-13 16:21:39.000000', NULL, 1),
(512221, 50256, 5792, '<td valign="top">Great concept. I wonder if the sky color might have been slightly overdone. Correct me if I am wrong.</td>', 'Great concept. I wonder if the sky color might have been slightly overdone. Correct me if I am wrong.', '2003-12-13 16:25:25.000000', NULL, 1),
(512224, 50049, 5792, '<td valign="top">This is a terrific image. The only fault is the halo around the leftmost end of the main subject. It is otherwise absolutely perfect.</td>', 'This is a terrific image. The only fault is the halo around the leftmost end of the main subject. It is otherwise absolutely perfect.', '2003-12-13 16:27:50.000000', NULL, 1),
(512228, 49583, 5792, '<td valign="top">Good color, nice shadow and decent setup. I like.</td>', 'Good color, nice shadow and decent setup. I like.', '2003-12-13 16:29:14.000000', NULL, 1),
(512229, 50271, 5792, '<td valign="top">The lighting reflection is harsh but otherwise a nice image. Superb focus</td>', 'The lighting reflection is harsh but otherwise a nice image. Superb focus', '2003-12-13 16:30:53.000000', NULL, 1),
(512230, 50080, 14601, '<td valign="top">Terrific shot. Just terrific. The best capture of the challenge theme, in my opinion.</td>', 'Terrific shot. Just terrific. The best capture of the challenge theme, in my opinion.', '2003-12-13 16:30:57.000000', NULL, 1),
(512234, 50105, 14601, '<td valign="top">Very nice photograph. Nicely lit; very sharp. Leaves me ( no pun intended ) guessing at the original colors, hence engages me. Well done.</td>', 'Very nice photograph. Nicely lit; very sharp. Leaves me ( no pun intended ) guessing at the original colors, hence engages me. Well done.', '2003-12-13 16:34:05.000000', NULL, 1),
(512235, 50278, 5792, '<td valign="top">Great perspective. High quality.</td>', 'Great perspective. High quality.', '2003-12-13 16:34:13.000000', NULL, 1),
(512240, 50289, 14601, '<td valign="top">Great setup, clever use of solids &amp; stripes at an angle, lighting is just right.</td>', 'Great setup, clever use of solids & stripes at an angle, lighting is just right.', '2003-12-13 16:38:34.000000', NULL, 1),
(512251, 50112, 5792, '<td valign="top">Great expressions and framing.</td>', 'Great expressions and framing.', '2003-12-13 16:50:42.000000', NULL, 1),
(512253, 50234, 5792, '<td valign="top">You should not be stung badly in voting for this image.</td>', 'You should not be stung badly in voting for this image.', '2003-12-13 16:53:20.000000', NULL, 1),
(512257, 49530, 5792, '<td valign="top">Some voters might make only hollow points in their comments and shoot it down, but it is a good image.</td>', 'Some voters might make only hollow points in their comments and shoot it down, but it is a good image.', '2003-12-13 17:02:34.000000', NULL, 1),
(512258, 49824, 5792, '<td valign="top">You nailed this challenge</td>', 'You nailed this challenge', '2003-12-13 17:03:28.000000', NULL, 1),
(512260, 50316, 5792, '<td valign="top">One of lif''e simple pleasures captured well.</td>', 'One of lif''e simple pleasures captured well.', '2003-12-13 17:05:09.000000', NULL, 1),
(512262, 49773, 5792, '<td valign="top">This is a very nice concept, but appears to be overworked in post processing (I am not guiltless of this in my own images for sure).<br/> <br/>It appears over sharpened with edge effects. A white halo around the blue handle is plainly visible. The deep blue of the handle and in the soup seems unnatural.</td>', 'This is a very nice concept, but appears to be overworked in post processing (I am not guiltless of this in my own images for sure). It appears over sharpened with edge effects. A white halo around the blue handle is plainly visible. The deep blue of the handle and in the soup seems unnatural.', '2003-12-13 17:09:16.000000', NULL, 1),
(512263, 50136, 2158, '<td valign="top">My feeling is that this would have worked better on a plain colour background.</td>', 'My feeling is that this would have worked better on a plain colour background.', '2003-12-13 17:10:34.000000', NULL, 1),
(512264, 49865, 5792, '<td valign="top">This image is well conceived, but is generally on the dark side and the front end of the coffee cup is out of focus and is distracting in the image.</td>', 'This image is well conceived, but is generally on the dark side and the front end of the coffee cup is out of focus and is distracting in the image.', '2003-12-13 17:10:50.000000', NULL, 1),
(512266, 50010, 5792, '<td valign="top">A good concept for this challenge. The horizon is not level and needs to be rotated clockwise to be level. The colors seem a bit unnatural.</td>', 'A good concept for this challenge. The horizon is not level and needs to be rotated clockwise to be level. The colors seem a bit unnatural.', '2003-12-13 17:13:38.000000', NULL, 1),
(512268, 50258, 5792, '<td valign="top">The idea is good but the general overall quality of the image could be better. It looks like it is the quality out of the camera and not from over processing by the photographer.</td>', 'The idea is good but the general overall quality of the image could be better. It looks like it is the quality out of the camera and not from over processing by the photographer.', '2003-12-13 17:15:59.000000', NULL, 1),
(512270, 50025, 5792, '<td valign="top">This would be a terrific image except that it looks like more noise reduction was performed on it than needed. Some voters will probably rate it lower for its white border.</td>', 'This would be a terrific image except that it looks like more noise reduction was performed on it than needed. Some voters will probably rate it lower for its white border.', '2003-12-13 17:19:53.000000', NULL, 1),
(512282, 50159, 5792, '<td valign="top">Voters should ''''line up'''' to give this a good score.<br/> <br/>Great lines. Composition outstanding.</td>', 'Voters should ''''line up'''' to give this a good score. Great lines. Composition outstanding.', '2003-12-13 17:32:30.000000', NULL, 1),
(512287, 50276, 5792, '<td valign="top">No chance you will get clipped on this image.<br/> <br/>An excellent image -  Composition, framing, lighting and technical quality all outstanding. This alone merits a high placing for this image. <br/> <br/>Add the simplicity of the subject and of the image itself and this one should get a blue ribbon next to it.</td>', 'No chance you will get clipped on this image. An excellent image -  Composition, framing, lighting and technical quality all outstanding. This alone merits a high placing for this image.  Add the simplicity of the subject and of the image itself and this one should get a blue ribbon next to it.', '2003-12-13 17:34:14.000000', NULL, 1),
(512288, 49669, 5792, '<td valign="top">Very clean image. Solid backgroun and nice grey scale accross the shoes. One of my favorites for this challenge.<br/> <br/>Voters should not boot this one.</td>', 'Very clean image. Solid backgroun and nice grey scale accross the shoes. One of my favorites for this challenge. Voters should not boot this one.', '2003-12-13 17:34:38.000000', NULL, 1),
(512289, 50275, 5792, '<td valign="top">Most voters will get the point of this submission. Good composition and lighting. Decent technical quality. Matches the challenge well.</td>', 'Most voters will get the point of this submission. Good composition and lighting. Decent technical quality. Matches the challenge well.', '2003-12-13 17:34:55.000000', NULL, 1),
(512290, 50259, 5792, '<td valign="top">Cats are great. You always basically know what they are thinking. This one appears to be saying, Do that again and you will regret it!  :)</td>', 'Cats are great. You always basically know what they are thinking. This one appears to be saying, Do that again and you will regret it!  :)', '2003-12-13 17:35:46.000000', NULL, 1),
(512291, 49844, 5792, '<td valign="top">No one will call you a drip for this fine image. :)</td>', 'No one will call you a drip for this fine image. :)', '2003-12-13 17:36:07.000000', NULL, 1),
(512292, 50279, 10848, '<td valign="top">This is very imaginative, and I love the play on the words in your title, the colors work wonderfully together, the lighting is great, good crop and I like the frame choice 10</td>', 'This is very imaginative, and I love the play on the words in your title, the colors work wonderfully together, the lighting is great, good crop and I like the frame choice 10', '2003-12-13 17:36:09.000000', NULL, 1),
(512293, 49813, 5792, '<td valign="top">You may have to pound it into voters, but this image should do well.</td>', 'You may have to pound it into voters, but this image should do well.', '2003-12-13 17:37:10.000000', NULL, 1),
(512294, 50301, 5792, '<td valign="top">Hope this image does not miss the mark.<br/> <br/>Interesting since the hammer head is not square on the nail.</td>', 'Hope this image does not miss the mark. Interesting since the hammer head is not square on the nail.', '2003-12-13 17:37:44.000000', NULL, 1),
(512295, 49611, 5792, '<td valign="top">If voters are abreast of current photographic trends then this should do OK.<br/> <br/>If your goal is to be unique, you achieved it. :) Decent job photographically.</td>', 'If voters are abreast of current photographic trends then this should do OK. If your goal is to be unique, you achieved it. :) Decent job photographically.', '2003-12-13 17:38:35.000000', NULL, 1),
(512296, 49716, 10848, '<td valign="top">This is adorable, shows alot of imagination, the snowman is just a little blurry, I like this alot 7</td>', 'This is adorable, shows alot of imagination, the snowman is just a little blurry, I like this alot 7', '2003-12-13 17:38:55.000000', NULL, 1),
(512297, 50064, 5792, '<td valign="top">Good idea!<br/> <br/>Voters should not leave you up in the air over this one''s score.</td>', 'Good idea! Voters should not leave you up in the air over this one''s score.', '2003-12-13 17:40:12.000000', NULL, 1),
(512298, 50330, 5792, '<td valign="top">You might get screwed a little bit by voters for a soft focus. The image is perfectly vertical and the border is good.</td>', 'You might get screwed a little bit by voters for a soft focus. The image is perfectly vertical and the border is good.', '2003-12-13 17:41:09.000000', NULL, 1),
(512299, 50194, 5792, '<td valign="top">Good subject for soft focus. You think the focus is just a hair to soft?</td>', 'Good subject for soft focus. You think the focus is just a hair to soft?', '2003-12-13 17:42:29.000000', NULL, 1),
(512300, 49813, 10848, '<td valign="top">good shot, clarity is great, lighting us great also 9</td>', 'good shot, clarity is great, lighting us great also 9', '2003-12-13 17:42:43.000000', NULL, 1),
(512302, 50326, 5792, '<td valign="top">Thie idea for this image is OK. Noise reduction would help it considerably.</td>', 'Thie idea for this image is OK. Noise reduction would help it considerably.', '2003-12-13 17:45:00.000000', NULL, 1),
(512304, 49911, 10848, '<td valign="top">this is an adorable child, very good shot, captured the eyes perfectly 9</td>', 'this is an adorable child, very good shot, captured the eyes perfectly 9', '2003-12-13 17:45:30.000000', NULL, 1),
(512307, 49886, 5792, '<td valign="top">You should not receive many pointed comments against this image.</td>', 'You should not receive many pointed comments against this image.', '2003-12-13 17:47:58.000000', NULL, 1),
(512312, 49779, 12332, '<td valign="top">good photo, but I would keep an eye on this fellow!</td>', 'good photo, but I would keep an eye on this fellow!', '2003-12-13 18:13:19.000000', NULL, 1),
(512315, 50136, 6130, '<td valign="top">Very good.</td>', 'Very good.', '2003-12-13 18:23:36.000000', NULL, 1),
(512318, 49873, 6130, '<td valign="top">Fantastic.</td>', 'Fantastic.', '2003-12-13 18:26:18.000000', NULL, 1),
(512320, 49504, 6130, '<td valign="top">This is very beautiful and good.</td>', 'This is very beautiful and good.', '2003-12-13 18:28:04.000000', NULL, 1),
(512335, 50273, 14593, '<td valign="top">very simple, but very interesting.....I like it!</td>', 'very simple, but very interesting.....I like it!', '2003-12-13 19:15:20.000000', NULL, 1),
(512337, 49591, 14593, '<td valign="top">nice idea.....simple lines.....love the bright red too!!</td>', 'nice idea.....simple lines.....love the bright red too!!', '2003-12-13 19:21:07.000000', NULL, 1),
(512338, 49583, 14593, '<td valign="top">simple.....crisp and vibrant....</td>', 'simple.....crisp and vibrant....', '2003-12-13 19:23:47.000000', NULL, 1),
(512341, 50054, 14593, '<td valign="top">very creative....something so simple looking not so simple....I like this!!</td>', 'very creative....something so simple looking not so simple....I like this!!', '2003-12-13 19:28:03.000000', NULL, 1),
(512344, 50275, 14593, '<td valign="top">As the photo was slowly downloading I could not tell what it was!   Very simple, but very eye-catching....</td>', 'As the photo was slowly downloading I could not tell what it was!   Very simple, but very eye-catching....', '2003-12-13 19:36:07.000000', NULL, 1),
(512346, 50038, 14593, '<td valign="top">haha.....you are right....men aren''t!  Just joking with you....great photo, and creative idea!!</td>', 'haha.....you are right....men aren''t!  Just joking with you....great photo, and creative idea!!', '2003-12-13 19:38:53.000000', NULL, 1),
(512347, 50227, 5534, '<td valign="top">I don''t know if it''s intentional, but the blurriness hurts this photo. 5</td>', 'I don''t know if it''s intentional, but the blurriness hurts this photo. 5', '2003-12-13 19:39:32.000000', NULL, 1),
(512367, 49716, 11295, '<td valign="top">This is exceptionally cute and well composed, but I don''t know if it fits with "simplicity" so much...</td>', 'This is exceptionally cute and well composed, but I don''t know if it fits with "simplicity" so much...', '2003-12-13 20:55:29.000000', NULL, 1),
(512368, 49779, 11295, '<td valign="top">This is profoundly strange... but you know, I like it. :)</td>', 'This is profoundly strange... but you know, I like it. :)', '2003-12-13 20:56:13.000000', NULL, 1),
(512369, 49714, 11295, '<td valign="top">I love the way you''ve framed this, and the colours are terrific.</td>', 'I love the way you''ve framed this, and the colours are terrific.', '2003-12-13 20:57:51.000000', NULL, 1),
(512370, 50113, 11295, '<td valign="top">Creepy, and pretty darned cool. Well done! I like the little red tinge.</td>', 'Creepy, and pretty darned cool. Well done! I like the little red tinge.', '2003-12-13 20:58:34.000000', NULL, 1),
(512372, 50000, 11295, '<td valign="top">This one is great. I love the contrast you got out of this shot. One of my favourites. Congrats!</td>', 'This one is great. I love the contrast you got out of this shot. One of my favourites. Congrats!', '2003-12-13 21:00:13.000000', NULL, 1),
(512373, 49763, 11295, '<td valign="top">Very pretty... I don''t know if I''d have chosen such a thick border though...</td>', 'Very pretty... I don''t know if I''d have chosen such a thick border though...', '2003-12-13 21:01:58.000000', NULL, 1),
(512374, 50090, 11295, '<td valign="top">This one is messing with my mind... there''s an interesting kind of 3D optical illusion going on here, which works against the simplicity of the composition. Still, I spent a lot more time looking at this one than many, and that says to me that this deserves high marks. Good eye for seeing this and capturing it.</td>', 'This one is messing with my mind... there''s an interesting kind of 3D optical illusion going on here, which works against the simplicity of the composition. Still, I spent a lot more time looking at this one than many, and that says to me that this deserves high marks. Good eye for seeing this and capturing it.', '2003-12-13 21:05:22.000000', NULL, 1),
(512375, 49504, 11295, '<td valign="top">Interesting concept, but a little dark and grainy... I''m not sure if that was your intention...</td>', 'Interesting concept, but a little dark and grainy... I''m not sure if that was your intention...', '2003-12-13 21:07:28.000000', NULL, 1),
(512379, 49855, 11295, '<td valign="top">:)</td>', ':)', '2003-12-13 21:10:55.000000', NULL, 1),
(512381, 49482, 11295, '<td valign="top">OK, but how does it fit the challenge?</td>', 'OK, but how does it fit the challenge?', '2003-12-13 21:11:57.000000', NULL, 1),
(512383, 50294, 11295, '<td valign="top">Fits the challenge nicely, but it''s really missing the ''wow'' factor that would give it higher scores.</td>', 'Fits the challenge nicely, but it''s really missing the ''wow'' factor that would give it higher scores.', '2003-12-13 21:14:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(512386, 49893, 11295, '<td valign="top">I like this one a lot. Great clarity. I think I see a ribbon in your future!</td>', 'I like this one a lot. Great clarity. I think I see a ribbon in your future!', '2003-12-13 21:15:34.000000', NULL, 1),
(512389, 50285, 11295, '<td valign="top">Nice, clear capture, but this seems way more dynamic than simple.</td>', 'Nice, clear capture, but this seems way more dynamic than simple.', '2003-12-13 21:29:00.000000', NULL, 1),
